AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01EZNZjJ1qK9E6yNsM2aMugs', arguments={'file_text': "(function () {
  const form = document.getElementById('contact-form');
  const status = document.getElementById('form-status');

  const fields = {
    name: {
      el: document.getElementById('name'),
      errorEl: document.getElementById('name-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Enter your full name.';
        return '';
      },
    },
    email: {
      el: document.getElementById('email'),
      errorEl: document.getElementById('email-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return 'Error: Enter your email address.';
        const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRe.test(v)) return 'Error: Enter a valid email like name@example.com.';
        return '';
      },
    },
    phone: {
      el: document.getElementById('phone'),
      errorEl: document.getElementById('phone-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return '';
        const digits = v.replace(/[\s\-().]/g, '');
        if (!/^\+?\d+$/.test(digits)) {
          return 'Error: Phone number can only contain digits, spaces, dashes, parentheses, and an optional leading +.';
        }
        const digitCount = digits.replace(/^\+/, '').length;
        if (digitCount < 10 || digitCount > 15) {
          return 'Error: Enter a phone number with 10 to 15 digits, e.g. 555-123-4567.';
        }
        return '';
      },
    },
  };

  function setError(field, message) {
    if (message) {
      field.errorEl.textContent = message;
      field.errorEl.hidden = false;
      field.el.setAttribute('aria-invalid', 'true');
    } else {
      field.errorEl.textContent = '';
      field.errorEl.hidden = true;
      field.el.removeAttribute('aria-invalid');
    }
  }

  Object.values(fields).forEach((field) => {
    field.el.addEventListener('blur', () => {
      setError(field, field.validate(field.el.value));
    });
    field.el.addEventListener('input', () => {
      if (field.el.getAttribute('aria-invalid') === 'true') {
        const msg = field.validate(field.el.value);
        if (!msg) setError(field, '');
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    status.textContent = '';
    status.classList.remove('success');

    let firstInvalid = null;
    Object.values(fields).forEach((field) => {
      const msg = field.validate(field.el.value);
      setError(field, msg);
      if (msg && !firstInvalid) firstInvalid = field.el;
    });

    if (firstInvalid) {
      firstInvalid.focus();
      status.textContent = 'Please fix the errors above and try again.';
      return;
    }

    status.textContent = 'Thanks! Your message has been sent. We\u2019ll be in touch soon.';
    status.classList.add('success');
    form.reset();
  });
})();
