  dom.window.document.getElementById('contact-form').dispatchEvent(new dom.window.Event('submit', { cancelable: true, bubbles: true }));
  await new Promise(r => setTimeout(r, 50));
  total += await run('After empty submit');

  const setVal = (id, v) => {
    const el = dom.window.document.getElementById(id);
    el.value = v;
    el.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
  };
  setVal('name', 'Jane');
  setVal('email', 'not-an-email');
  setVal('phone', 'abc');
  dom.window.document.getElementById('contact-form').dispatchEvent(new dom.window.Event('submit', { cancelable: true, bubbles: true }));
  await new Promise(r => setTimeout(r, 50));
  total += await run('After invalid submit');

  console.log('\nTotal violations:', total);
  process.exit(total === 0 ? 0 : 1);
})();
